`property` 是内置类型，它是数据描述符——同时实现了 `__get__`、`__set__`、`__delete__`。这意味着 `property` 的优先级高于实例 `__dict__`，这解释了为什么 `obj.prop = value` 会调用 setter 而不是覆盖实例字典。

手写一个简化版 property 来理解其内部逻辑：
```python
class MyProperty:
    """简化版 property，实现数据描述符协议"""
    def __init__(self, fget=None, fset=None, fdel=None, doc=None):
        self.fget = fget
        self.fset = fset
        self.fdel = fdel
        self.__doc__ = doc or (fget.__doc__ if fget else None)

    def __get__(self, obj, objtype=None):
        if obj is None:          # 类访问 MyClass.prop → 返回描述符自身
            return self
        if self.fget is None:
            raise AttributeError("unreadable attribute")
        return self.fget(obj)    # 实例访问 obj.prop → 调用 getter

    def __set__(self, obj, value):
        if self.fset is None:
            raise AttributeError("can't set attribute")
        self.fset(obj, value)

    def __delete__(self, obj):
        if self.fdel is None:
            raise AttributeError("can't delete attribute")
        self.fdel(obj)

    def getter(self, fget):      # 允许 @prop.getter 语法
        return type(self)(fget, self.fset, self.fdel, self.__doc__)
    def setter(self, fset):
        return type(self)(self.fget, fset, self.fdel, self.__doc__)
    def deleter(self, fdel):
        return type(self)(self.fget, self.fset, fdel, self.__doc__)
```

注意 `__get__` 中的 `obj is None` 分支——当通过类访问时（`MyClass.prop`），`obj` 是 `None`，property 返回自身，这样你才能访问 `.fget`、`.setter` 等方法。这也是为什么 `type(obj).__dict__['prop']` 拿到的是描述符对象本身。

Python 3.6 引入了 `__set_name__(self, owner, name)` 钩子，在类创建阶段（`type.__new__`）自动调用，把属性名告诉描述符实例。在此之前，描述符必须在构造函数中显式传入属性名：`price = PositiveNumber('price')`，这既冗余又容易出错（复制粘贴忘改名）。

```python
class ValidatedField:
    def __init__(self, validator):
        self.validator = validator
        self.name = None           # 由 __set_name__ 填充

    def __set_name__(self, owner, name):
        self.name = f"_{name}"     # 加下划线前缀，避免 __set__ 无限递归

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.__dict__.get(self.name)

    def __set__(self, obj, value):
        if self.validator and not self.validator(value):
            raise ValueError(f"Validation failed for {self.name}: {value}")
        obj.__dict__[self.name] = value
```

`__set_name__` 的调用时机是 `type.__new__` 中对命名空间里每个值调用 `type.__init_subclass__` 和 `__set_name__`（CPython 3.6+）。所以如果描述符是动态添加到已有类上的（`setattr(MyClass, 'x', desc)`），`__set_name__` 不会被调用。

# === 1. C3 MRO 推导与验证 ===
class A: pass
class B(A): pass
class C(A): pass
class D(B, C): pass

print('D MRO:', [c.__name__ for c in D.__mro__])
# ['D', 'B', 'C', 'A', 'object'] — A 只出现一次，排在 B、C 之后

# super() 沿 MRO 调用
class Base:
    def who(self): return 'Base'
class Left(Base):
    def who(self): return 'Left'
class Right(Base):
    def who(self): return 'Right'
class Child(Left, Right):
    def who(self): return 'Child -> ' + super().who()

print(Child().who())  # Child -> Left — super() 查 MRO 下一个是 Left

# === 2. 描述符实现带验证的字段 ===
class ValidatedField:
    """数据描述符：类型检查 + 自定义验证"""
    def __init__(self, expected_type, validator=None):
        self.expected_type = expected_type
        self.validator = validator
        self.name = None

    def __set_name__(self, owner, name):
        self.name = f"_{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.__dict__.get(self.name)

    def __set__(self, obj, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name}: expected {self.expected_type.__name__}, got {type(value).__name__}")
        if self.validator and not self.validator(value):
            raise ValueError(f"{self.name}: validation failed for {value!r}")
        obj.__dict__[self.name] = value

class Product:
    name = ValidatedField(str, validator=lambda v: len(v) > 0)
    price = ValidatedField(float, validator=lambda v: v > 0)
    quantity = ValidatedField(int, validator=lambda v: v >= 0)

p = Product()
p.name = 'Widget'
p.price = 9.99
p.quantity = 100
print(f"{p.name}: ${p.price} x {p.quantity}")
# Widget: $9.99 x 100

try:
    p.price = -5
except ValueError as e:
    print(f"验证拒绝: {e}")  # _price: validation failed for -5

# === 3. 元类实现子类注册（含 __init_subclass__ 对比） ===
# 方式一：元类
class HandlerMeta(type):
    _registry = {}
    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if hasattr(cls, 'action') and cls.action is not None:
            HandlerMeta._registry[cls.action] = cls
        return cls

class Handler(metaclass=HandlerMeta):
    action = None

class LoginHandler(Handler):
    action = 'login'

class LogoutHandler(Handler):
    action = 'logout'

print('元类注册:', HandlerMeta._registry)
# {'login': <class 'LoginHandler'>, 'logout': <class 'LogoutHandler'>}

# 方式二：__init_subclass__（更简单）
class ServiceBase:
    _services = {}
    def __init_subclass__(cls, service_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        name = service_name or cls.__name__
        ServiceBase._services[name] = cls

class AuthService(ServiceBase, service_name='auth'): pass
class DataService(ServiceBase, service_name='data'): pass

print('__init_subclass__ 注册:', ServiceBase._services)
# {'auth': <class 'AuthService'>, 'data': <class 'DataService'>}
